using DraftDatastore.Application.Players; using DraftDatastore.Domain.Entities; using DraftDatastore.Persistence; using Microsoft.EntityFrameworkCore;
namespace DraftDatastore.Infrastructure.Players;
public sealed class EfPlayerRepository(DraftDatastoreDbContext db) : IPlayerRepository {
 private static IQueryable<Player> Include(IQueryable<Player> q)=>q.Include(x=>x.Nationality).Include(x=>x.PlayingEra).Include(x=>x.Aliases).Include(x=>x.Images).Include(x=>x.PlayerPositions).ThenInclude(x=>x.Position);
 public async Task<PagedResult<Player>> SearchAsync(PlayerSearchRequest request,CancellationToken ct){var q=Include(db.Players.AsNoTracking());if(!string.IsNullOrWhiteSpace(request.Search)){var s=request.Search.Trim();q=q.Where(x=>x.FullName.Contains(s)||x.Aliases.Any(a=>a.Alias.Contains(s)));}if(request.PositionId is int pos)q=q.Where(x=>x.PlayerPositions.Any(pp=>pp.PositionId==pos));if(request.NationalityId is int nat)q=q.Where(x=>x.NationalityId==nat);if(request.PlayingEraId is int era)q=q.Where(x=>x.PlayingEraId==era);if(request.ActiveFromYear is int fromYear&&request.ActiveToYear is int toYear)q=q.Where(x=>x.PlayingEra.StartYear<=toYear&&x.PlayingEra.EndYear>=fromYear);if(request.Rank is int rank)q=q.Where(x=>x.OverallRank==rank);q=(request.SortBy.ToLowerInvariant(),request.Descending) switch {("name",true)=>q.OrderByDescending(x=>x.FullName),("name",false)=>q.OrderBy(x=>x.FullName),("goalcredit",true)=>q.OrderByDescending(x=>x.GoalCreditPoints),("goalcredit",false)=>q.OrderBy(x=>x.GoalCreditPoints),("assistcredit",true)=>q.OrderByDescending(x=>x.AssistCreditPoints),("assistcredit",false)=>q.OrderBy(x=>x.AssistCreditPoints),("defensivecredit",true)=>q.OrderByDescending(x=>x.DefensiveCreditPoints),("defensivecredit",false)=>q.OrderBy(x=>x.DefensiveCreditPoints),(_,true)=>q.OrderByDescending(x=>x.OverallRank),_=>q.OrderBy(x=>x.OverallRank)};var total=await q.CountAsync(ct);var items=await q.Skip((request.PageNumber-1)*request.PageSize).Take(request.PageSize).ToListAsync(ct);return new(items,request.PageNumber,request.PageSize,total);}
 public Task<Player?> GetAsync(Guid id,bool includeDeleted,CancellationToken ct){IQueryable<Player> q=includeDeleted?db.Players.IgnoreQueryFilters():db.Players;return Include(q).SingleOrDefaultAsync(x=>x.Id==id,ct);}
 public Task AddAsync(Player player,CancellationToken ct)=>db.Players.AddAsync(player,ct).AsTask(); public Task SaveAsync(CancellationToken ct)=>db.SaveChangesAsync(ct); }

